import{obterJSON,endereco,consultaLimpa,pontuarCorrespondencia,idiomas}from'./comum.js';
const lista=v=>Array.isArray(v)?v:v==null?[]:[v],texto=v=>String(v??'').trim();
export async function pesquisarPressbooks(q,o={}){
 const termo=consultaLimpa(q);if(!termo)return{livros:[],total:0,temMais:false};
 const pagina=Math.max(1,o.pagina||1),u=new URL('/api/pressbooks',location.origin);u.searchParams.set('q',termo);u.searchParams.set('pagina',String(pagina));
 try{const d=await obterJSON(u,14000,2);if(d?.taxaLimite)return{livros:[],total:0,temMais:false};const hits=lista(d?.hits?.hits),livros=hits.map(h=>{const x=h?._source||{},m=x.mainEntityOfPage||{},origem=endereco(typeof m==='string'?m:m?.id||m?.url||x.url||x.id),id=texto(h?._id||x.id||origem);if(!id||!origem)return null;const autores=lista(x.creator).map(a=>typeof a==='string'?a:a?.name).filter(Boolean).map(String),lic=typeof x.license==='string'?x.license:x?.license?.id||x?.license?.url||x.rights;return{id:`pressbooks:${id}`,fonte:'pressbooks',provedor:'Pressbooks Directory',titulo:texto(x.name||x.title)||'Sem título',autores,idiomas:idiomas(x.inLanguage||x.language||[]),capa:endereco(typeof x.image==='string'?x.image:x?.image?.url||x.thumbnailUrl),descricao:texto(x.description||x.abstract),acessoLivre:true,dominioPublico:false,tipoAcesso:'Livro educacional aberto',licenca:texto(lic)||'Recurso educacional aberto indexado pelo OERSI.',origem,ler:origem,texto:null,formatos:[]}}).filter(Boolean);for(const l of livros)l.relevancia=pontuarCorrespondencia(termo,l.titulo,l.autores);livros.sort((a,b)=>(b.relevancia||0)-(a.relevancia||0));const total=Number(d?.hits?.total?.value??d?.hits?.total)||livros.length;return{livros,total,temMais:pagina*20<total&&hits.length>0}}catch{return{livros:[],total:0,temMais:false}}
}
